import React, { useEffect, useState } from 'react';
import { Link, useNavigate, useParams } from 'react-router-dom';
import Typography from '@mui/material/Typography';
import Breadcrumbs from '@mui/material/Breadcrumbs';
import HomeBreadcrumbs from '../../Assets/Img/home-breadcrumbs.svg';
import Tab from '@mui/material/Tab';
import TabContext from '@mui/lab/TabContext';
import TabList from '@mui/lab/TabList';
import TabPanel from '@mui/lab/TabPanel';
import { Button, Col, Row } from 'react-bootstrap';
import MenuItem from '@mui/material/MenuItem';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import Proactive from './Proactive';
import Reactive from './Reactive';
import { useDispatch, useSelector } from 'react-redux';
import { getUserListData } from 'store/reducers/User/user.slice';
import { getContactSourcesListDataActive } from 'store/reducers/Admin/Events/ContactSources/contactSources.slice';
import Loader from 'Components/Common/Loader';
import PdfIcon from '../../Assets/Img/pdf-icon.svg';
import html2canvas from 'html2canvas';
import jsPDF from 'jspdf';

import {
  getEnquiriesData,
  setEnquirieDetail,
  updateEnquiries,
} from 'store/reducers/Enquiry/enquiries.slice';
import { cancelResons } from 'utils/FieldValues';
import moment from 'moment';

export default function EditBooking() {
  const { bookingId } = useParams();
  const dispatch = useDispatch();

  const { enquirieLoading, enquirieDetail } = useSelector(
    ({ enquiries }) => enquiries,
  );
  const { userPermissionDetail } = useSelector(({ user }) => user);

  const { activeUserList } = useSelector(({ user }) => user);
  const navigate = useNavigate();
  const { activeContactSourcesList } = useSelector(
    ({ contactSources }) => contactSources,
  );

  // const [value, setValue] = useState('1');
  const [value, setValue] = useState(enquirieDetail?.is_pro_active ? '1' : '2');
  const [ownerSelect, setOwnerSelect] = useState('');
  const [ownerStatus, setOwnerStatus] = useState(false);

  const handleChange = (event, newValue) => {
    setValue(newValue);
  };

  useEffect(() => {
    dispatch(getEnquiriesData(bookingId));
  }, [bookingId]);

  useEffect(() => {
    dispatch(getUserListData());
    dispatch(
      getContactSourcesListDataActive({
        is_active: true,
      }),
    );
  }, [dispatch]);

  const handleUpdateBooking = () => {
    dispatch(
      updateEnquiries({
        _id: enquirieDetail?._id,
        owner: ownerSelect === 'select' ? '' : ownerSelect,
      }),
    );
    setOwnerStatus(true);
  };

  useEffect(() => {
    return () => {
      dispatch(setEnquirieDetail({}));
    };
  }, []);

  useEffect(() => {
    if (Object.keys(enquirieDetail).length && !enquirieDetail?.is_booking) {
      navigate(`/edit-enquiries/${bookingId}`);
    }
    setOwnerSelect(enquirieDetail.owner ? enquirieDetail.owner : '');
  }, [enquirieDetail]);

  const [pdfLoader, setPdfLoader] = useState(false);

  const generatePDF = () => {
    setPdfLoader(true);
    const inputElement = document.getElementById('edit-booking-pdf-view-show');

    if (inputElement) {
      html2canvas(inputElement).then(canvas => {
        const pageWidth = 290;
        const pageHeight = 295;
        const aspectRatio = canvas.width / canvas.height;
        const pdf = new jsPDF({
          orientation: aspectRatio > 1 ? 'l' : 'p',
          unit: 'mm',
          format: [pageWidth, pageHeight],
          precision: 16, // Set a higher precision
          dpi: 300, // Set a higher DPI
        });
        const imgData = canvas.toDataURL('image/png');
        const imgWidth = pageWidth;
        const imgHeight = imgWidth / aspectRatio;
        const marginTop = 0;
        const marginBottom = 5;
        const totalPages = Math.ceil(
          (imgHeight + marginTop + marginBottom) / pageHeight,
        );
        for (let page = 1; page <= totalPages; page++) {
          if (page > 1) {
            pdf.addPage();
          }
          const offsetY = -pageHeight * (page - 1) - marginTop;
          pdf.addImage(imgData, 'PNG', 0, offsetY, imgWidth, imgHeight);
          if (page === totalPages) {
            break;
          }
        }
        const blob = pdf.output('blob');
        const url = URL.createObjectURL(blob);
        window.open(url);
        setPdfLoader(false);
        const downloadLink = document.getElementById('downloadLink');
        downloadLink.href = url;
        const pdfFileName = 'your-pdf-filename.pdf';
        downloadLink.download = pdfFileName;
        downloadLink.click();
        URL.revokeObjectURL(url);
        setPdfLoader(false);
      });
    }
  };

  return (
    <div className="inner_wrapper">
      {(pdfLoader || enquirieLoading) && <Loader />}
      <div className="breadcrumb_wrap">
        <Breadcrumbs aria-label="breadcrumb">
          <Link to="/">
            <img src={HomeBreadcrumbs} alt="Home Icon" />
          </Link>
          <Link to="/bookings">Bookings</Link>
          <Typography>Edit booking</Typography>
        </Breadcrumbs>
      </div>
      <div className="page_title">
        <h1>Edit booking</h1>
      </div>
      {enquirieDetail?.exclusive_booking && (
        <div className="exclusive_booking_wrap">
          <p>Exclusive Booking</p>
        </div>
      )}
      <div id="edit-booking-pdf-view-show">
        <TabContext value={value}>
          <div className="edit_booking_top_wrap bg_white_box">
            <Row className="align-items-center">
              <Col xxl={7} className="mb-2 mb-xxl-0">
                <div className="d-flex align-items-center">
                  <TabList
                    onChange={handleChange}
                    aria-label="lab API tabs example"
                  >
                    <Tab label="Proactive" value="1" />
                    <Tab label="Reactive" value="2" />
                  </TabList>
                  <div className="owner_select d-flex">
                    <div className="form-group inline mb-0">
                      <span className="label">Owner:</span>
                      <FormControl fullWidth>
                        <Select
                          labelId="Enquiries-label"
                          id="Enquiries"
                          value={ownerSelect}
                          onChange={event => setOwnerSelect(event.target.value)}
                          defaultValue="Select"
                          className="select_wrap"
                          disabled={
                            userPermissionDetail?.admin &&
                            userPermissionDetail?.assign
                              ? false
                              : true
                          }
                        >
                          <MenuItem value="Select" disabled>
                            Select
                          </MenuItem>
                          {activeUserList?.map(item => {
                            return (
                              <MenuItem value={item?._id} key={item?._id}>
                                {item?.public_name} ({item?.username})
                              </MenuItem>
                            );
                          })}
                        </Select>
                      </FormControl>
                    </div>
                    {userPermissionDetail?.admin &&
                      userPermissionDetail?.assign && (
                        <Button
                          className="btn_border small ms-3"
                          onClick={handleUpdateBooking}
                        >
                          {ownerStatus ? 'Updated' : 'Save'}
                        </Button>
                      )}
                  </div>
                </div>
              </Col>

              {enquirieDetail?.booking_info?.provisional_places > 0 && (
                <Col xxl={5} className="mb-2 mb-xxl-0">
                  <div className="right_booking_detail">
                    <ul>
                      <li
                        className={
                          +enquirieDetail?.overdue_by > 0
                            ? 'due'
                            : enquirieDetail?.overdue_by < 0
                            ? 'overdue'
                            : enquirieDetail?.overdue_by === 0
                            ? 'today'
                            : ''
                        }
                      >
                        Hold Period:{' '}
                        <span>
                          {enquirieDetail?.hold_period
                            ? enquirieDetail?.hold_period + ' Days'
                            : '0 Days'}
                        </span>
                      </li>
                      <li
                        className={
                          +enquirieDetail?.overdue_by > 0
                            ? 'due'
                            : enquirieDetail?.overdue_by < 0
                            ? 'overdue'
                            : enquirieDetail?.overdue_by === 0
                            ? 'today'
                            : ''
                        }
                      >
                        Percentage Left:{' '}
                        <span>
                          {enquirieDetail?.percentage_left
                            ? enquirieDetail?.percentage_left + '%'
                            : '0'}
                        </span>
                      </li>
                      <li
                        className={
                          +enquirieDetail?.overdue_by > 0
                            ? 'due'
                            : enquirieDetail?.overdue_by < 0
                            ? 'overdue'
                            : enquirieDetail?.overdue_by === 0
                            ? 'today'
                            : ''
                        }
                      >
                        Places Left:{' '}
                        <span>
                          {enquirieDetail?.places_left
                            ? enquirieDetail?.places_left
                            : 0}
                          /
                          {enquirieDetail?.total_places
                            ? enquirieDetail?.total_places
                            : 0}
                        </span>
                      </li>
                      <li
                        className={
                          +enquirieDetail?.overdue_by > 0
                            ? 'due'
                            : enquirieDetail?.overdue_by < 0
                            ? 'overdue'
                            : enquirieDetail?.overdue_by === 0
                            ? 'today'
                            : ''
                        }
                      >
                        {+enquirieDetail?.overdue_by > 0
                          ? 'Due in'
                          : enquirieDetail?.overdue_by < 0
                          ? 'Overdue By'
                          : enquirieDetail?.overdue_by === 0
                          ? 'Due '
                          : ''}{' '}
                        <span>
                          {enquirieDetail?.overdue_by
                            ? enquirieDetail?.overdue_by
                            : ''}
                        </span>
                        {+enquirieDetail?.overdue_by > 0
                          ? ' days'
                          : enquirieDetail?.overdue_by < 0
                          ? ' DAYS'
                          : enquirieDetail?.overdue_by === 0
                          ? ' TODAY'
                          : ''}
                      </li>
                    </ul>
                  </div>
                </Col>
              )}
            </Row>
          </div>
          {enquirieDetail?.invoice_text_visible && (
            <div className="view_invoice_wrapper">
              <Link to={`/edit-bookings/invoices/${enquirieDetail?._id}`}>
                There is a new invoice available which has not been sent to the
                customer - click here to view the invoices
              </Link>
            </div>
          )}
          {enquirieDetail?.eticket_text_visible && (
            <div className="e_ticket_wrapper">
              <Link to={`/edit-bookings/booking-e-ticket/${bookingId}`}>
                THE eTICKETS ARE OUT OF DATE
              </Link>
            </div>
          )}
          {enquirieDetail?.is_cancelled && (
            <>
              <div className="contact_alert_Wrap py-2 my-2">
                THIS BOOKING IS CANCELLED - by {enquirieDetail?.cancel_user} on{' '}
                {enquirieDetail?.cancel_time
                  ? moment(enquirieDetail?.cancel_time).format(
                      'ddd Do MMM YYYY',
                    )
                  : ''}
              </div>
              <div className="bg_gray_box px-3 py-2 d-block">
                <p className="mb-1">
                  CANCELLATION REASON:{' '}
                  {
                    cancelResons.find(
                      item =>
                        item?.value === parseFloat(enquirieDetail?.reason),
                    )?.label
                  }
                </p>
                <p className="mb-1">DETAILS: {enquirieDetail?.cancel_notes}</p>
              </div>
            </>
          )}
          {(Boolean(enquirieDetail?.is_payment) ||
            Boolean(enquirieDetail?.is_invoice)) &&
            !enquirieDetail?.booking_info?.confirmed_places > 0 &&
            !enquirieDetail?.booking_info?.provisional_places > 0 && (
              <div className="contact_alert_Wrap py-2 my-2">
                APPEARS TO HAVE BEEN CANCELLED - Places are at Zero
              </div>
            )}
          <div className="edit_booking_main_wrap">
            <TabPanel value="1">
              <Proactive
                pages="booking"
                enquirieDetail={enquirieDetail}
                activeContactSourcesList={activeContactSourcesList}
                id={bookingId}
                dispatch={dispatch}
              />
            </TabPanel>
            <TabPanel value="2">
              <Reactive
                pages="booking"
                enquirieDetail={enquirieDetail}
                activeContactSourcesList={activeContactSourcesList}
                id={bookingId}
                dispatch={dispatch}
              />
            </TabPanel>
          </div>
        </TabContext>
      </div>
      <div className="pdf_icon" onClick={generatePDF}>
        <img src={PdfIcon} alt="pdf icon" />
      </div>
    </div>
  );
}
